255	func (s *Store) Register(id, site string) (Device, bool, error) {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		if state, ok := s.devices[id]; ok {
259			return cloneDevice(state.device), false, nil
260		}
261		now := s.now().UTC()
262		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
263		if s.wal != nil {
264			if err := s.wal.appendRecord(recRegister, walRegister{
265				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
266			}); err != nil {
267				return Device{}, false, storageUnavailable(err)
268			}
269		}
270		s.devices[id] = &deviceState{
271			device:  device,
272			known:   make(map[string]knownSample),
273			batches: make(map[string]storedBatch),
