279	// GetRetention returns the device's retention limit and history counters.
280	func (s *Store) GetRetention(id string) (RetentionStatus, error) {
281		s.mu.RLock()
282		defer s.mu.RUnlock()
283		state, ok := s.devices[id]
284		if !ok {
285			return RetentionStatus{}, ErrDeviceNotFound
286		}
