290	// SetRetention changes the per-device history cap. A maxEvents of 0 removes
291	// the limit; values 1..maxRetentionEvents keep at most that many newest
292	// samples. Lowering the limit trims the oldest events immediately by receive
293	// sequence; raising it only affects future writes. Device activity, last
294	// telemetry, alerts and other devices are untouched.
295	func (s *Store) SetRetention(id string, maxEvents int64) (RetentionStatus, error) {
296		s.mu.Lock()
297		defer s.mu.Unlock()
298		state, ok := s.devices[id]
299		if !ok {
300			return RetentionStatus{}, ErrDeviceNotFound
301		}
302		trimThrough := planTrimThrough(state.eventBase, state.maxSequence(), maxEvents)
303		if s.wal != nil {
304			if err := s.wal.appendRecord(recRetention, walRetention{
305				DeviceID:    id,
306				MaxEvents:   maxEvents,
307				TrimThrough: trimThrough,
308			}); err != nil {
309				return RetentionStatus{}, storageUnavailable(err)
310			}
311		}
312		state.maxEvents = maxEvents
313		state.applyTrim(trimThrough)
314		return state.retentionStatus(), nil
315	}
