317	// RecordTelemetry stores a live telemetry sample in the device history. The
318	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
319	// observed time is the server receive time.
320	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
321		s.mu.Lock()
322		defer s.mu.Unlock()
323		state, ok := s.devices[id]
324		if !ok {
325			return Device{}, ErrDeviceNotFound
326		}
327		now := s.now().UTC()
328		sequence := state.maxSequence() + 1
329		trimThrough := planTrimThrough(state.eventBase, sequence, state.maxEvents)
330		eval := newAlertEvaluator(state)
331		eval.evaluate(sequence, now, values)
332		if s.wal != nil {
333			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
334				DeviceID:    id,
335				Sequence:    sequence,
336				ObservedAt:  now,
337				Values:      values,
338				TrimThrough: trimThrough,
339				Alerts:      eval.created,
340				Ended:       eval.ended,
341			}); err != nil {
342				return Device{}, storageUnavailable(err)
343			}
344		}
345		state.events = append(state.events, Event{
346			Sequence:   sequence,
347			ObservedAt: now,
348			Values:     cloneTelemetry(values),
349		})
350		state.device.LastSeenAt = now
351		state.device.LastTelemetry = cloneTelemetry(values)
352		eval.commit()
353		state.applyTrim(trimThrough)
354		return cloneDevice(state.device), nil
355	}
356	
357	// Replay validates and commits a batch atomically. repeat is true when the
358	// batchId was already committed with identical content and the first receipt
359	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
360	// ErrBatchConflict when any sample clashes with an existing eventId or the
361	// batchId was previously committed with different ordered content; in either
362	// conflict case no state changes.
363	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
364		s.mu.Lock()
365		defer s.mu.Unlock()
366		state, ok := s.devices[id]
367		if !ok {
368			return ReplayReceipt{}, false, ErrDeviceNotFound
369		}
370	
371		if previous, exists := state.batches[batchID]; exists {
372			if !sameOrderedSamples(previous.samples, samples) {
373				return ReplayReceipt{}, false, ErrBatchConflict
374			}
375			return cloneReceipt(previous.receipt), true, nil
376		}
377	
378		// Validate every sample against the device's dedup memory before assigning
379		// anything, so a conflict rolls back without leaving sequences, events or
380		// receipts. A previously trimmed event is still known here: identical
381		// content stays a duplicate (and never re-enters history), different
382		// content still conflicts the whole batch.
383		type plan struct {
384			sample   Sample
385			sequence int64
386			dup      bool
387		}
388		planned := make([]plan, len(samples))
389		nextSequence := state.maxSequence() + 1
390		for i, sample := range samples {
391			if known, seen := state.known[sample.EventID]; seen {
392				if !sameInstant(known.observedAt, sample.ObservedAt) ||
393					!sameValues(known.values, sample.Values) {
394					return ReplayReceipt{}, false, ErrBatchConflict
395				}
396				planned[i] = plan{sample, known.sequence, true}
397				continue
398			}
399			planned[i] = plan{sample, nextSequence, false}
400			nextSequence++
401		}
402		maxSequence := nextSequence - 1
403		trimThrough := planTrimThrough(state.eventBase, maxSequence, state.maxEvents)
404	
405		// Build the receipt from the plan: only samples that matched a committed
406		// event before this batch are duplicates.
407		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
408		for _, entry := range planned {
409			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
410				EventID:   entry.sample.EventID,
411				Sequence:  entry.sequence,
412				Duplicate: entry.dup,
413			})
414			if entry.dup {
415				receipt.Duplicate++
416			} else {
417				receipt.NewCount++
418			}
419		}
420	
421		// Evaluate the batch's new samples against the device's enabled rules, in
422		// array order (which is receive-sequence order). Duplicates never judge,
423		// create, end or refresh alerts. A trigger and a recovery inside one batch
424		// both produce alert changes, all committed together with the batch.
425		eval := newAlertEvaluator(state)
426		for _, entry := range planned {
427			if entry.dup {
428				continue
429			}
430			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
431		}
432	
433		// Durable commit point: the whole batch is one record, synced before any
434		// in-memory state changes and before success is reported. A failure here
435		// leaves sequences, history, receipts, device state and alert changes
436		// untouched.
437		lastNew := -1
438		for i, entry := range planned {
439			if !entry.dup {
440				lastNew = i
441			}
442		}
443		var committedAt time.Time
444		if s.wal != nil {
445			record := walReplay{
446				DeviceID:    id,
447				BatchID:     batchID,
448				Samples:     make([]walSample, len(samples)),
449				Receipt:     receipt,
450				TrimThrough: trimThrough,
451				Alerts:      eval.created,
452				Ended:       eval.ended,
453			}
454			for i, sample := range samples {
455				record.Samples[i] = walSample{
456					EventID:    sample.EventID,
457					ObservedAt: sample.ObservedAt,
458					Values:     sample.Values,
459				}
460			}
461			if lastNew >= 0 {
462				committedAt = s.now().UTC()
463				record.LastSeenAt = &committedAt
464				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
465			}
466			if err := s.wal.appendRecord(recReplay, record); err != nil {
467				return ReplayReceipt{}, false, storageUnavailable(err)
468			}
469		}
470	
471		// Commit: append new samples in array order. Every new sample registers in
472		// the durable dedup memory, even when the retention limit immediately
473		// trims its event out of history.
474		for _, entry := range planned {
475			if entry.dup {
476				continue
477			}
478			state.events = append(state.events, Event{
479				Sequence:   entry.sequence,
480				ObservedAt: entry.sample.ObservedAt,
481				Values:     cloneTelemetry(entry.sample.Values),
482			})
483			state.known[entry.sample.EventID] = knownSample{
484				sequence:   entry.sequence,
485				observedAt: entry.sample.ObservedAt,
486				values:     cloneTelemetry(entry.sample.Values),
487			}
488		}
489	
490		committed := make([]Sample, len(samples))
491		copy(committed, samples)
492		for i := range committed {
493			committed[i].Values = cloneTelemetry(samples[i].Values)
494		}
495		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
496	
497		if lastNew >= 0 {
498			if s.wal == nil {
499				committedAt = s.now().UTC()
500			}
501			state.device.LastSeenAt = committedAt
502			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
503		}
504		eval.commit()
505		// Enforce the retention limit after the whole batch is accepted: all new
506		// samples judged, kept their assigned sequences and appear on the receipt;
507		// only the oldest excess events leave history.
508		state.applyTrim(trimThrough)
509		return receipt, false, nil
510	}
511	
512	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
513		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
514		return receipt
515	}
