1	package fleet
2	
3	// Remote diagnostics HTTP handlers. A fleet operator creates and cancels
4	// tasks and reads lists, details and audit trails; the simulated device claims
5	// the earliest claimable task and reports its outcome. Task operations never
6	// touch telemetry, rules, configuration or device activity times.
7	
8	import (
9		"encoding/json"
10		"errors"
11		"net/http"
12		"strconv"
13		"strings"
14	)
15	
16	// taskCreateRequest is the raw task creation envelope.
17	type taskCreateRequest struct {
18		RequestID       string `json:"requestId"`
19		DurationSeconds *int   `json:"durationSeconds"`
20	}
21	
22	// taskReportRequest is the device outcome envelope.
23	type taskReportRequest struct {
24		ReceiptID  string          `json:"receiptId"`
25		Credential string          `json:"credential"`
26		Success    *bool           `json:"success"`
27		Reason     string          `json:"reason"`
28		Result     json.RawMessage `json:"result"`
29	}
30	
31	func (h *handler) createTask(w http.ResponseWriter, r *http.Request) {
32		var request taskCreateRequest
33		if err := decodeSingleJSON(r, &request); err != nil {
34			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
35			return
36		}
37		requestID := strings.TrimSpace(request.RequestID)
38		if requestID == "" {
39			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "requestId is required"})
40			return
41		}
42		if request.DurationSeconds == nil {
43			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "durationSeconds is required"})
44			return
45		}
46		if *request.DurationSeconds < taskMinDuration || *request.DurationSeconds > taskMaxDuration {
47			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "durationSeconds must be between 1 and 60"})
48			return
49		}
50	
51		task, repeat, err := h.store.CreateTask(r.PathValue("id"), requestID, *request.DurationSeconds)
52		if errors.Is(err, ErrDeviceNotFound) {
53			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
54			return
55		}
56		if errors.Is(err, ErrTaskConflict) {
57			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
58			return
59		}
60		if errors.Is(err, ErrStorageUnavailable) {
61			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
62			return
63		}
64		if err != nil {
65			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
66			return
67		}
68		status := http.StatusCreated
69		if repeat {
70			status = http.StatusOK
71		}
72		writeJSON(w, status, task)
73	}
74	
75	func (h *handler) listTasks(w http.ResponseWriter, r *http.Request) {
76		tasks, err := h.store.ListTasks(r.PathValue("id"))
77		if errors.Is(err, ErrDeviceNotFound) {
78			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
79			return
80		}
81		if errors.Is(err, ErrStorageUnavailable) {
82			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
83			return
84		}
85		if err != nil {
86			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
87			return
88		}
89		writeJSON(w, http.StatusOK, map[string]any{"tasks": tasks})
90	}
91	
92	func (h *handler) getTask(w http.ResponseWriter, r *http.Request) {
93		taskID, err := parseTaskID(r)
94		if err != nil {
95			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
96			return
97		}
98		task, err := h.store.GetTask(r.PathValue("id"), taskID)
99		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrTaskNotFound) {
100			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
101			return
102		}
103		if errors.Is(err, ErrStorageUnavailable) {
104			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
105			return
106		}
107		if err != nil {
108			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
109			return
110		}
111		writeJSON(w, http.StatusOK, task)
112	}
113	
114	// claimTask serves the simulated device's pull. Only the earliest-created task
115	// that has reached its claimable time is returned; 204 means nothing is
116	// claimable (including when another task is still executing).
117	func (h *handler) claimTask(w http.ResponseWriter, r *http.Request) {
118		view, claimed, err := h.store.ClaimTask(r.PathValue("id"))
119		if errors.Is(err, ErrDeviceNotFound) {
120			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
121			return
122		}
123		if errors.Is(err, ErrStorageUnavailable) {
124			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
125			return
126		}
127		if err != nil {
128			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
129			return
130		}
131		if !claimed {
132			w.WriteHeader(http.StatusNoContent)
133			return
134		}
135		writeJSON(w, http.StatusOK, view)
136	}
137	
138	func (h *handler) reportTask(w http.ResponseWriter, r *http.Request) {
139		taskID, err := parseTaskID(r)
140		if err != nil {
141			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "taskId must be a positive integer"})
142			return
143		}
144		var request taskReportRequest
145		if err := decodeSingleJSON(r, &request); err != nil {
146			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
147			return
148		}
149		receiptID := strings.TrimSpace(request.ReceiptID)
150		if receiptID == "" {
