1	package fleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"math/big"
9		"time"
10	)
11	
12	// Config delivery lets a fleet operator publish complete JSON configurations
13	// to a registered device. A simulated device reads only the latest target
14	// version, applies it, and reports a success or failure receipt. Versions are
15	// per-device integers starting at 1; before the first publish both the target
16	// and the applied version read as 0.
17	//
18	// History is immutable: publishing never edits an old version, so rolling back
19	// means re-publishing the old content as a new version. Every device keeps its
20	// own versions, publish-request deduplication records and receipts.
21	
22	// ConfigView is one published configuration version with its complete content.
23	type ConfigView struct {
24		Version     int64           `json:"version"`
25		Content     json.RawMessage `json:"config"`
26		PublishedAt time.Time       `json:"publishedAt"`
27	}
28	
29	// ConfigPublishResult is returned (and stored for idempotent retries) by a
30	// successful publish.
31	type ConfigPublishResult struct {
32		RequestID   string          `json:"requestId"`
33		Version     int64           `json:"version"`
34		Content     json.RawMessage `json:"config"`
35		PublishedAt time.Time       `json:"publishedAt"`
36	}
37	
38	// ConfigReceipt is one device-reported application outcome, retained in
39	// receive order.
40	type ConfigReceipt struct {
41		ReceiptID  string    `json:"receiptId"`
42		Version    int64     `json:"version"`
43		Success    bool      `json:"success"`
44		Reason     string    `json:"reason,omitempty"`
45		ReceivedAt time.Time `json:"receivedAt"`
46	}
47	
48	// ConfigStatus summarises where a device stands.
49	type ConfigStatus struct {
50		TargetVersion  int64  `json:"targetVersion"`
51		AppliedVersion int64  `json:"appliedVersion"`
52		FailureReason  string `json:"-"`
53	}
54	
55	var (
56		// ErrConfigConflict covers a stale publish base, a publish requestId reused
57		// with a different base or content, a stale/contradictory receipt, and a
58		// receiptId reused with different content.
59		ErrConfigConflict = errors.New("configuration conflict")
60		// ErrConfigVersionUnknown is reported for a receipt for a version that was
61		// never published to the device.
62		ErrConfigVersionUnknown = errors.New("configuration version unknown")
63	)
64	
65	type publishedConfig struct {
66		content     json.RawMessage
67		publishedAt time.Time
68	}
69	
70	// storedPublish remembers a committed publish so the same requestId can be
71	// recognised as an idempotent retry or a conflicting reuse.
72	type storedPublish struct {
73		baseVersion int64
74		content     json.RawMessage
75		result      ConfigPublishResult
76	}
77	
78	type configState struct {
79		versions  []publishedConfig        // index + 1 is the version number
80		applied   int64                    // highest successfully applied version
81		publishes map[string]storedPublish // requestId -> first publish
82		receipts  []ConfigReceipt          // receive order
83		byReceipt map[string]ConfigReceipt // receiptId -> first receipt
84	}
85	
86	func newConfigState() *configState {
87		return &configState{
88			publishes: make(map[string]storedPublish),
89			byReceipt: make(map[string]ConfigReceipt),
90		}
91	}
92	
93	// ensureConfig lazily attaches config state to a device; callers must hold the
94	// store lock (write mode when allocate is wanted).
95	func (state *deviceState) ensureConfig() *configState {
96		if state.config == nil {
97			state.config = newConfigState()
98		}
99		return state.config
100	}
101	
102	// PublishConfig applies one optimistic-concurrency publish.
103	//
104	// A requestId already committed on this device is an idempotent retry when the
105	// base and content match (the first result is returned with repeat=true) and a
106	// conflict otherwise. A fresh requestId only creates a version when baseVersion
107	// equals the current target; the loser of a concurrent race therefore gets
108	// ErrConfigConflict without consuming a version.
109	func (s *Store) PublishConfig(id, requestID string, baseVersion int64, content json.RawMessage) (ConfigPublishResult, bool, error) {
110		s.mu.Lock()
111		defer s.mu.Unlock()
112		state, ok := s.devices[id]
113		if !ok {
114			return ConfigPublishResult{}, false, ErrDeviceNotFound
115		}
116		cfg := state.ensureConfig()
117	
118		if previous, seen := cfg.publishes[requestID]; seen {
119			if previous.baseVersion != baseVersion || !sameJSON(previous.content, content) {
120				return ConfigPublishResult{}, false, ErrConfigConflict
121			}
122			return clonePublishResult(previous.result), true, nil
123		}
124	
125		target := int64(len(cfg.versions))
126		if baseVersion != target {
127			return ConfigPublishResult{}, false, ErrConfigConflict
128		}
129		version := target + 1
130		now := s.now().UTC()
131		stored := storedPublish{
132			baseVersion: baseVersion,
133			content:     cloneJSON(content),
134			result: ConfigPublishResult{
135				RequestID:   requestID,
136				Version:     version,
137				Content:     cloneJSON(content),
138				PublishedAt: now,
139			},
140		}
141		if s.wal != nil {
142			if err := s.wal.appendRecord(recConfigPublish, walConfigPublish{
143				DeviceID:    id,
144				RequestID:   requestID,
145				BaseVersion: baseVersion,
146				Version:     version,
147				Content:     cloneJSON(content),
148				PublishedAt: now,
149			}); err != nil {
150				return ConfigPublishResult{}, false, storageUnavailable(err)
151			}
152		}
153		cfg.versions = append(cfg.versions, publishedConfig{
154			content:     cloneJSON(content),
155			publishedAt: now,
156		})
157		cfg.publishes[requestID] = stored
158		return clonePublishResult(stored.result), false, nil
159	}
160	
161	// PendingConfig returns the latest target version when the device has not yet
162	// applied it. It returns ok=false when nothing was ever published or the
163	// latest version is already applied; reads never mutate state and old versions
164	// skipped by a newer target are not delivered individually.
165	func (s *Store) PendingConfig(id string) (ConfigView, bool, error) {
166		s.mu.RLock()
167		defer s.mu.RUnlock()
168		state, ok := s.devices[id]
169		if !ok {
170			return ConfigView{}, false, ErrDeviceNotFound
171		}
172		if state.config == nil {
173			return ConfigView{}, false, nil
174		}
175		cfg := state.config
176		target := int64(len(cfg.versions))
177		if target == 0 || cfg.applied >= target {
178			return ConfigView{}, false, nil
179		}
180		latest := cfg.versions[target-1]
181		return ConfigView{
182			Version:     target,
183			Content:     cloneJSON(latest.content),
184			PublishedAt: latest.publishedAt,
185		}, true, nil
186	}
187	
188	// RecordConfigReceipt validates and stores one application receipt.
189	//
190	// A repeated receiptId with identical version/result/reason returns the first
191	// receipt (repeat=true); a reused receiptId with different content conflicts.
192	// A version that was never published is ErrConfigVersionUnknown; a new receipt
193	// below the applied version and a failure for an already applied version
194	// conflict. Success advances the applied version (a success lagging behind the
195	// target is recorded and advances only up to its own version); failure never
196	// advances, so the latest target stays readable for a retry.
197	func (s *Store) RecordConfigReceipt(id, receiptID string, version int64, success bool, reason string) (ConfigReceipt, bool, error) {
198		s.mu.Lock()
199		defer s.mu.Unlock()
200		state, ok := s.devices[id]
201		if !ok {
202			return ConfigReceipt{}, false, ErrDeviceNotFound
203		}
204		cfg := state.ensureConfig()
205	
206		// A reason belongs to failures only; a successful result never carries one.
207		if success {
208			reason = ""
209		}
210	
211		if previous, seen := cfg.byReceipt[receiptID]; seen {
212			if previous.Version != version || previous.Success != success || previous.Reason != reason {
213				return ConfigReceipt{}, false, ErrConfigConflict
214			}
215			return previous, true, nil
216		}
217	
218		if version < 1 || version > int64(len(cfg.versions)) {
219			return ConfigReceipt{}, false, ErrConfigVersionUnknown
220		}
221		if version < cfg.applied {
222			return ConfigReceipt{}, false, ErrConfigConflict
223		}
224		if !success && version <= cfg.applied {
225			// The version already succeeded; it cannot fail afterwards.
226			return ConfigReceipt{}, false, ErrConfigConflict
227		}
228	
229		now := s.now().UTC()
230		receipt := ConfigReceipt{
231			ReceiptID:  receiptID,
232			Version:    version,
233			Success:    success,
234			Reason:     reason,
235			ReceivedAt: now,
236		}
237		if s.wal != nil {
238			if err := s.wal.appendRecord(recConfigReceipt, walConfigReceipt{
239				DeviceID:   id,
240				ReceiptID:  receiptID,
241				Version:    version,
242				Success:    success,
243				Reason:     reason,
244				ReceivedAt: now,
245			}); err != nil {
246				return ConfigReceipt{}, false, storageUnavailable(err)
247			}
248		}
249		cfg.receipts = append(cfg.receipts, receipt)
250		cfg.byReceipt[receiptID] = receipt
251		if success && version > cfg.applied {
252			cfg.applied = version
253		}
254		return receipt, false, nil
255	}
256	
257	// ListConfigs returns every published version in ascending version order, each
258	// with its complete content.
259	func (s *Store) ListConfigs(id string) ([]ConfigView, error) {
260		s.mu.RLock()
261		defer s.mu.RUnlock()
262		state, ok := s.devices[id]
263		if !ok {
264			return nil, ErrDeviceNotFound
265		}
266		if state.config == nil {
267			return []ConfigView{}, nil
268		}
269		cfg := state.config
270		views := make([]ConfigView, 0, len(cfg.versions))
271		for i, published := range cfg.versions {
272			views = append(views, ConfigView{
273				Version:     int64(i + 1),
274				Content:     cloneJSON(published.content),
275				PublishedAt: published.publishedAt,
276			})
277		}
278		return views, nil
279	}
