1	package fleet
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"strings"
8		"sync"
9		"testing"
10		"time"
11	)
12	
13	// --- response types and helpers ---------------------------------------------
14	
15	type taskResponse struct {
16		ID              int64           `json:"id"`
17		RequestID       string          `json:"requestId"`
18		DurationSeconds int             `json:"durationSeconds"`
19		Status          string          `json:"status"`
20		Attempts        int             `json:"attempts"`
21		CreatedAt       time.Time       `json:"createdAt"`
22		NextClaimableAt time.Time       `json:"nextClaimableAt"`
23		ClaimedAt       *time.Time      `json:"claimedAt"`
24		Deadline        *time.Time      `json:"deadline"`
25		Result          json.RawMessage `json:"result"`
26		FailureReason   string          `json:"failureReason"`
27		CompletedAt     *time.Time      `json:"completedAt"`
28	}
29	
30	type claimResponse struct {
31		Task       taskResponse `json:"task"`
32		Attempt    int          `json:"attempt"`
33		Credential string       `json:"credential"`
34		Deadline   time.Time    `json:"deadline"`
35	}
36	
37	type taskReportResponse struct {
38		ReceiptID  string          `json:"receiptId"`
39		Success    bool            `json:"success"`
40		Reason     string          `json:"reason"`
41		Result     json.RawMessage `json:"result"`
42		ReceivedAt time.Time       `json:"receivedAt"`
43	}
44	
45	type taskAuditResponse struct {
46		Seq        int64     `json:"seq"`
47		Event      string    `json:"event"`
48		FromStatus string    `json:"fromStatus"`
49		ToStatus   string    `json:"toStatus"`
50		Attempt    int       `json:"attempt"`
51		At         time.Time `json:"at"`
52		Reason     string    `json:"reason"`
53	}
54	
55	func taskBody(requestID string, seconds int) string {
56		return fmt.Sprintf(`{"requestId":%q,"durationSeconds":%d}`, requestID, seconds)
57	}
58	
59	func reportBody(receiptID, credential string, success bool, reason, result string) string {
60		if success {
61			return fmt.Sprintf(`{"receiptId":%q,"credential":%q,"success":true,"result":%s}`, receiptID, credential, result)
62		}
63		return fmt.Sprintf(`{"receiptId":%q,"credential":%q,"success":false,"reason":%q}`, receiptID, credential, reason)
64	}
65	
66	func createTask(t *testing.T, h http.Handler, device, body string, wantStatus int) taskResponse {
67		t.Helper()
68		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks", device), body)
69		if r.Code != wantStatus {
70			t.Fatalf("create task status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
71		}
72		if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
73			return decodeBody[taskResponse](t, r)
74		}
75		return taskResponse{}
76	}
77	
78	func claimTask(t *testing.T, h http.Handler, device string, wantStatus int) claimResponse {
79		t.Helper()
80		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks/claim", device), "")
81		if r.Code != wantStatus {
82			t.Fatalf("claim status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
83		}
84		if wantStatus == http.StatusOK {
85			return decodeBody[claimResponse](t, r)
86		}
87		return claimResponse{}
88	}
89	
90	func reportTask(t *testing.T, h http.Handler, device string, taskID int64, body string, wantStatus int) taskReportResponse {
91		t.Helper()
92		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks/%d/reports", device, taskID), body)
93		if r.Code != wantStatus {
94			t.Fatalf("report status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
95		}
96		if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
97			return decodeBody[taskReportResponse](t, r)
98		}
99		return taskReportResponse{}
100	}
101	
102	func getTask(t *testing.T, h http.Handler, device string, taskID int64, wantStatus int) taskResponse {
103		t.Helper()
104		r := doRequest(t, h, http.MethodGet, fmt.Sprintf("/v1/devices/%s/tasks/%d", device, taskID), "")
105		if r.Code != wantStatus {
106			t.Fatalf("get task status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
107		}
108		if wantStatus == http.StatusOK {
109			return decodeBody[taskResponse](t, r)
110		}
111		return taskResponse{}
112	}
113	
114	func cancelTask(t *testing.T, h http.Handler, device string, taskID int64, wantStatus int) taskResponse {
115		t.Helper()
116		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/tasks/%d/cancel", device, taskID), "")
117		if r.Code != wantStatus {
118			t.Fatalf("cancel status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
119		}
120		if wantStatus == http.StatusOK {
121			return decodeBody[taskResponse](t, r)
