223	func TestTaskReportFailureAndBackoff(t *testing.T) {
224		store, clock := newClockStore()
225		h := NewHandler(store)
226		mustRegister(t, h, "dev-1")
227		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
228	
229		// First failure.
230		claim := claimTask(t, h, "dev-1", http.StatusOK)
231		reportTask(t, h, "dev-1", claim.Task.ID,
232			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
233		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
234		if task.Status != "waiting" || task.FailureReason != "disk full" || task.Attempts != 1 {
235			t.Fatalf("after first failure: %+v", task)
236		}
237		if !task.NextClaimableAt.Equal(clock.UTC().Add(1 * time.Second)) {
238			t.Fatalf("next claimable = %s, want +1s", task.NextClaimableAt)
239		}
240		claimTask(t, h, "dev-1", http.StatusNoContent)
241	
242		// After the backoff, claim again.
243		*clock = clock.Add(2 * time.Second)
244		claim = claimTask(t, h, "dev-1", http.StatusOK)
245		if claim.Attempt != 2 {
246			t.Fatalf("attempt = %d, want 2", claim.Attempt)
247		}
248		reportTask(t, h, "dev-1", claim.Task.ID,
249			reportBody("rcpt-2", claim.Credential, false, "still full", ""), http.StatusCreated)
250		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
251		if task.Status != "waiting" || task.Attempts != 2 {
252			t.Fatalf("after second failure: %+v", task)
253		}
254		if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
255			t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
256		}
257	
258		// Third failure ends the task.
259		*clock = clock.Add(3 * time.Second)
260		claim = claimTask(t, h, "dev-1", http.StatusOK)
261		if claim.Attempt != 3 {
262			t.Fatalf("attempt = %d, want 3", claim.Attempt)
263		}
264		reportTask(t, h, "dev-1", claim.Task.ID,
265			reportBody("rcpt-3", claim.Credential, false, "gave up", ""), http.StatusCreated)
266		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
267		if task.Status != "failed" || task.CompletedAt == nil {
268			t.Fatalf("after third failure: %+v", task)
269		}
270		claimTask(t, h, "dev-1", http.StatusNoContent)
271	}
