273	func TestTaskReportFailureRetry(t *testing.T) {
274		store, clock := newClockStore()
275		h := NewHandler(store)
276		mustRegister(t, h, "dev-1")
277		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
278	
279		claim := claimTask(t, h, "dev-1", http.StatusOK)
280		first := reportTask(t, h, "dev-1", claim.Task.ID,
281			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
282		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
283		nextClaimable := task.NextClaimableAt
284	
285		// An identical retry is the received receipt again: 200 with the first
286		// receiptId, reason and receive time.
287		*clock = clock.Add(500 * time.Millisecond)
288		retry := reportTask(t, h, "dev-1", claim.Task.ID,
289			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
290		if retry.ReceiptID != first.ReceiptID || retry.Reason != first.Reason || !retry.ReceivedAt.Equal(first.ReceivedAt) {
291			t.Fatalf("retry = %+v, want the first receipt %+v", retry, first)
292		}
293	
294		// The retry does not accumulate a failure, re-time the wait or add audit.
295		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
296		if task.Status != "waiting" || !task.NextClaimableAt.Equal(nextClaimable) {
297			t.Fatalf("retry changed the task: %+v", task)
298		}
299		audit := listAudit(t, h, "dev-1", claim.Task.ID)
300		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed" {
301			t.Fatalf("audit after retry = %s", got)
302		}
303	
304		// Same receiptId with a changed reason or flipped to success -> 409, and
305		// the stored receipt is untouched.
306		reportTask(t, h, "dev-1", claim.Task.ID,
307			reportBody("rcpt-1", claim.Credential, false, "other reason", ""), http.StatusConflict)
308		reportTask(t, h, "dev-1", claim.Task.ID,
309			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
310		again := reportTask(t, h, "dev-1", claim.Task.ID,
311			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
312		if !again.ReceivedAt.Equal(first.ReceivedAt) || again.Reason != "disk full" {
313			t.Fatalf("receipt after conflicts = %+v", again)
314		}
315	
316		// A new receiptId with the stale credential is rejected and does not take
317		// the receiptId: the same receiptId is accepted once the task is claimed
318		// again and reported with the fresh credential.
319		reportTask(t, h, "dev-1", claim.Task.ID,
320			reportBody("rcpt-2", claim.Credential, false, "too early", ""), http.StatusConflict)
321	
322		// After the backoff the task is claimed again; the old receipt still
323		// replays with the original (now stale) credential and neither the replay
324		// nor a content conflict disturbs the running attempt.
325		*clock = nextClaimable.Add(time.Second)
326		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
327		if claim2.Attempt != 2 {
328			t.Fatalf("re-claim attempt = %d, want 2", claim2.Attempt)
329		}
330		retry = reportTask(t, h, "dev-1", claim.Task.ID,
331			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
332		if !retry.ReceivedAt.Equal(first.ReceivedAt) {
333			t.Fatalf("retry after re-claim = %+v, want receivedAt %s", retry, first.ReceivedAt)
334		}
335		reportTask(t, h, "dev-1", claim.Task.ID,
336			reportBody("rcpt-1", claim.Credential, false, "changed", ""), http.StatusConflict)
337		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
338		if task.Status != "in_progress" || task.Attempts != 2 || task.Deadline == nil || !task.Deadline.Equal(claim2.Deadline) {
339			t.Fatalf("running attempt disturbed: %+v", task)
340		}
341	
342		// The device reports the new attempt's failure with a fresh receiptId and
343		// the current credential; it joins the usual accumulation and backoff.
344		reportTask(t, h, "dev-1", claim.Task.ID,
345			reportBody("rcpt-2", claim2.Credential, false, "still full", ""), http.StatusCreated)
346		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
347		if task.Status != "waiting" || task.FailureReason != "still full" {
348			t.Fatalf("after second failure: %+v", task)
349		}
350		if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
351			t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
352		}
353		audit = listAudit(t, h, "dev-1", claim.Task.ID)
354		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed,claimed,failed" {
355			t.Fatalf("audit = %s", got)
356		}
357	}
